33	import static org.junit.jupiter.api.Assertions.assertEquals;
34	import static org.junit.jupiter.api.Assertions.assertTrue;
35	
36	/**
37	 * 真实多线程并发测试：验证 H2 行锁下不超卖、终态唯一、额度不重复释放/不变负。
38	 */
39	@SpringBootTest
40	@ActiveProfiles("test")
41	class ExposureConcurrencyTest {
42	
43	    /** 固定时钟：所有并发申请落在同一 UTC 日，预占均保持 RESERVED（不触发到期）。 */
44	    static class FixedClock extends Clock {
45	        private final Instant fixed;
46	
47	        FixedClock(Instant fixed) {
48	            this.fixed = fixed;
49	        }
50	
51	        @Override
52	        public ZoneId getZone() {
53	            return ZoneOffset.UTC;
54	        }
55	
56	        @Override
57	        public Clock withZone(ZoneId zone) {
58	            throw new UnsupportedOperationException();
59	        }
60	
61	        @Override
62	        public Instant instant() {
63	            return fixed;
64	        }
65	    }
66	
67	    static final Instant BASE = Instant.parse("2026-09-22T10:00:00Z");
68	    static final LocalDate DAY = LocalDate.of(2026, 9, 22);
69	
70	    @org.springframework.boot.test.context.TestConfiguration
71	    static class TestClockConfig {
72	        @org.springframework.context.annotation.Bean
73	        @org.springframework.context.annotation.Primary
74	        Clock fixedClock() {
75	            return new FixedClock(BASE);
76	        }
77	    }
78	
79	    @Autowired
80	    ExposureService service;
81	    @Autowired
82	    JdbcTemplate jdbc;
83	
84	    @BeforeEach
85	    void clean() {
86	        jdbc.update("DELETE FROM idempotency_record");
87	        jdbc.update("DELETE FROM exposure_reservation");
88	        jdbc.update("DELETE FROM quota_visitor_ledger");
89	        jdbc.update("DELETE FROM quota_total_ledger");
90	        jdbc.update("DELETE FROM campaign");
91	    }
92	
93	    @AfterAll
94	    static void releaseDatabase(@Autowired JdbcTemplate jdbc) {
95	        jdbc.execute("SHUTDOWN");
96	    }
97	
98	    @Test
99	    @DisplayName("并发申请超过总额度：成功数恰好等于总额度，账目不超卖")
100	    void concurrentApply_doesNotOversell() throws Exception {
101	        int totalCap = 20;
102	        int threads = 100;
103	        service.createCampaign(new CreateCampaignRequest("req-c", "cap", totalCap, 100_000));
104	
105	        ExecutorService pool = Executors.newFixedThreadPool(16);
106	        CountDownLatch start = new CountDownLatch(1);
107	        AtomicInteger success = new AtomicInteger();
108	        AtomicInteger rejected = new AtomicInteger();
109	        Set<String> reservationIds = Collections.synchronizedSet(new HashSet<>());
110	
111	        for (int i = 0; i < threads; i++) {
112	            final int idx = i;
113	            pool.submit(() -> {
114	                try {
115	                    start.await();
116	                    ReservationResponse r = service.apply(
117	                            new ApplyExposureRequest("req-a-" + idx, "cap", "visitor-" + idx));
118	                    success.incrementAndGet();
119	                    reservationIds.add(r.reservationId());
120	                } catch (ApiException ex) {
121	                    if (ex.getStatus().value() == 429) {
122	                        rejected.incrementAndGet();
123	                    } else {
124	                        throw ex;
125	                    }
126	                } catch (InterruptedException e) {
127	                    Thread.currentThread().interrupt();
128	                }
129	            });
130	        }
131	        start.countDown();
132	        pool.shutdown();
133	        assertTrue(pool.awaitTermination(30, TimeUnit.SECONDS), "并发任务应在超时前完成");
134	
135	        assertEquals(totalCap, success.get(), "成功预占数必须等于总额度");
136	        assertEquals(threads - totalCap, rejected.get(), "其余请求必须为 429");
137	        assertEquals(totalCap, reservationIds.size(), "预占单编号必须唯一");
138	
139	        QuotaResponse quota = service.queryQuota("cap", null, DAY);
140	        assertEquals(totalCap, quota.usedTotal());
141	        assertEquals(0, quota.remainingTotal());
142	    }
143	
144	    @Test
145	    @DisplayName("同一预占并发确认/取消：只允许一个终态，额度不重复释放、不变负")
146	    void concurrentConfirmAndCancel_singleTerminal_noDoubleRelease() throws Exception {
147	        service.createCampaign(new CreateCampaignRequest("req-c", "cap", 1, 1));
148	        ReservationResponse r = service.apply(new ApplyExposureRequest("req-a", "cap", "v1"));
149	
150	        int threads = 24;
151	        ExecutorService pool = Executors.newFixedThreadPool(threads);
152	        CountDownLatch start = new CountDownLatch(1);
153	        AtomicInteger confirmed = new AtomicInteger();
154	        AtomicInteger cancelled = new AtomicInteger();
155	        AtomicInteger conflicts = new AtomicInteger();
156	
157	        for (int i = 0; i < threads; i++) {
158	            final boolean confirm = i % 2 == 0;
159	            final int idx = i;
160	            pool.submit(() -> {
161	                try {
162	                    start.await();
163	                    ReservationResponse result = confirm
164	                            ? service.confirm(r.reservationId(),
165	                                    new ReservationActionRequest("req-t-" + idx))
166	                            : service.cancel(r.reservationId(),
167	                                    new ReservationActionRequest("req-t-" + idx));
168	                    if (result.status().name().equals("CONFIRMED")) {
169	                        confirmed.incrementAndGet();
170	                    } else {
171	                        cancelled.incrementAndGet();
172	                    }
173	                } catch (ApiException ex) {
174	                    if (ex.getStatus().value() == 409) {
175	                        conflicts.incrementAndGet();
176	                    } else {
177	                        throw ex;
178	                    }
179	                } catch (InterruptedException e) {
180	                    Thread.currentThread().interrupt();
181	                }
182	            });
183	        }
184	        start.countDown();
185	        pool.shutdown();
186	        assertTrue(pool.awaitTermination(30, TimeUnit.SECONDS), "并发任务应在超时前完成");
187	
188	        // 确认与取消各 12 个线程；胜出方向的同向后继操作返回原状态，异向全部 409
189	        assertTrue(confirmed.get() == 0 || cancelled.get() == 0,
190	                "只允许存在一种终态，实际 confirmed=" + confirmed.get() + " cancelled=" + cancelled.get());
191	        assertEquals(12, confirmed.get() + cancelled.get(), "胜出方向的所有调用返回同一终态");
192	        assertEquals(12, conflicts.get(), "异向操作必须全部为 409");
193	
194	        ReservationResponse detail = service.getReservation(r.reservationId());
195	        int usedTotal = jdbc.queryForObject(
196	                "SELECT used_total FROM quota_total_ledger WHERE campaign_id = 'cap' AND utc_date = ?",
197	                Integer.class, java.sql.Date.valueOf(DAY));
198	        int usedVisitor = jdbc.queryForObject(
199	                "SELECT used_visitor FROM quota_visitor_ledger "
200	                        + "WHERE campaign_id = 'cap' AND visitor_id = 'v1' AND utc_date = ?",
201	                Integer.class, java.sql.Date.valueOf(DAY));
202	        assertTrue(usedTotal >= 0 && usedVisitor >= 0, "账目不得为负");
203	        if (detail.status().name().equals("CANCELLED")) {
204	            assertEquals(0, usedTotal, "取消后总额度应恰好释放一次");
205	            assertEquals(0, usedVisitor, "取消后访客额度应恰好释放一次");
206	        } else {
207	            assertEquals(1, usedTotal, "确认后总额度保持占用");
208	            assertEquals(1, usedVisitor, "确认后访客额度保持占用");
209	        }
210	    }
211	
212	    @Test
213	    @DisplayName("同一 requestId 并发重放：业务只执行一次，响应一致")
214	    void concurrentSameRequestId_executesOnce() throws Exception {
215	        service.createCampaign(new CreateCampaignRequest("req-c", "cap", 100, 100));
216	
217	        int threads = 16;
218	        ExecutorService pool = Executors.newFixedThreadPool(threads);
219	        CountDownLatch start = new CountDownLatch(1);
220	        Set<String> reservationIds = Collections.synchronizedSet(new HashSet<>());
221	        AtomicInteger errors = new AtomicInteger();
222	
223	        for (int i = 0; i < threads; i++) {
224	            pool.submit(() -> {
225	                try {
226	                    start.await();
227	                    ReservationResponse r = service.apply(
228	                            new ApplyExposureRequest("same-key", "cap", "visitor-x"));
229	                    reservationIds.add(r.reservationId());
230	                } catch (Exception e) {
231	                    errors.incrementAndGet();
232	                }
233	            });
234	        }
235	        start.countDown();
236	        pool.shutdown();
237	        assertTrue(pool.awaitTermination(30, TimeUnit.SECONDS));
238	
239	        assertEquals(0, errors.get(), "并发同键重放不应报错");
240	        assertEquals(1, reservationIds.size(), "业务只执行一次");
241	        assertEquals(1, service.queryQuota("cap", "visitor-x", DAY).usedVisitor());
242	    }
243	}
