        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String operator,
        @NotBlank @Size(max = 64) String campaignId,
        @NotNull @Size(min = 1, max = 200) List<@Valid ReceiptItem> items
) {
